// Component instances (docs/wireframe-mode.md → Semantic components): a group with
// `component: { kind, props, size? }` whose children are generated by the library's
// `build(props, size)`. Rebuilt when `component` changed (props edited, resized, new instance)
// and on load; the generated children get stable ids `<instance id>~<index path>`.
import type { Draft } from 'immer';
import type { ComponentNode, GroupNode, SceneNode } from '@/model';
import { getComponent } from '../../library/registry';
import { resizableAxes, resolveProps } from '../../library/types';
import { harvestIcons } from '../../icons';
import { plain, type PipelineContext, type WireframeStep } from '../../types';

/** Gives built children stable ids derived from the instance id (deterministic rebuilds keep render identity cheap). */
function assignIds(children: SceneNode[], prefix: string): SceneNode[] {
  return children.map((c, i) => {
    const id = `${prefix}~${i}`;
    return c.type === 'group' ? { ...c, id, children: assignIds(c.children, id) } : { ...c, id };
  });
}

/**
 * Builds an instance's children for its current `component` (or `size` when given) into the draft.
 * Exported for the layout step, which sizes instances and needs their hug height.
 * Returns the built height, or null for an unknown kind.
 */
export function buildComponentInto(node: Draft<ComponentNode>, size?: { width: number; height?: number }): number | null {
  const def = getComponent(node.component.kind);
  if (!def) return null;
  const width = size?.width ?? node.component.size?.width ?? def.defaultSize.width;
  const props = resolveProps(def, node.component.props as Record<string, unknown>, node.component.resolved);
  // Icons the instance was saved with stay drawn even before the app loads the libraries.
  harvestIcons(plain(node.children) as SceneNode[]);
  let built;
  try {
    // `height`: the layout fixes it (fixed or fill sizing); the box is that tall whatever build returns.
    built = def.build(props, size?.height !== undefined && resizableAxes(def).height ? { width, height: size.height } : { width });
  } catch (err) {
    // A broken component must not break the document: keep what was built before.
    console.warn(`Component "${def.kind}" failed to build`, err);
    return node.component.size?.height ?? def.defaultSize.height;
  }
  // The box is as tall as the layout fixed it, but never shorter than what the component drew (a resizable
  // height is a minimum: content never overflows). Components that follow their content get no height.
  const height = size?.height !== undefined ? Math.max(size.height, built.height) : built.height;
  const children = assignIds(built.children, node.id);
  if (JSON.stringify(children) !== JSON.stringify(node.children)) node.children = children as Draft<SceneNode>[];
  const cur = node.component.size;
  if (!cur || cur.width !== width || cur.height !== height) node.component.size = { width, height };
  return height;
}

/**
 * Index paths of the instances to rebuild. Walks plain nodes only; skips subtrees that did not change.
 * Instances placed by a stack / grid are left to the layout step, which builds them at their slot's size.
 */
function stale(nodes: readonly SceneNode[], ctx: PipelineContext, path: number[], out: number[][], parentLays = false) {
  nodes.forEach((n, i) => {
    if (n.type !== 'group') return;
    const prev = ctx.previous(n.id);
    if (ctx.phase !== 'load' && prev === n) return; // untouched subtree (immer structural sharing)
    if (n.component) {
      if (parentLays && n.layoutItem?.position !== 'free') return;
      // Generated children are never instances to rebuild on their own.
      if (ctx.phase === 'load' || !prev || (prev as GroupNode).component !== n.component || (prev as GroupNode).layoutItem?.height !== n.layoutItem?.height) out.push([...path, i]);
      return;
    }
    stale(n.children, ctx, [...path, i], out, !!n.layout);
  });
}

/**
 * Rebuilds an instance that is not placed by a layout (free, or on a screen without a stack). Like in a
 * stack, one whose definition hugs its width follows its content when its props change (a FAB gets a label:
 * the pill grows). A width the user set by resizing is respected: it becomes `layoutItem.width` (fixed) and
 * is no longer re-hugged. Files keep their widths on load.
 */
function rebuildFree(node: Draft<ComponentNode>, ctx: PipelineContext) {
  const def = getComponent(node.component.kind);
  const prev = ctx.phase === 'load' ? undefined : (ctx.previous(node.id) as ComponentNode | undefined);
  const was = prev?.component?.size;
  const now = node.component.size;
  const w = node.layoutItem?.width;
  const axes = def ? resizableAxes(def) : { width: true, height: true };
  const h = node.layoutItem?.height;
  // A height the user set by resizing becomes `layoutItem.height` (fixed), like the width below.
  if (def && axes.height && was && now && (h === undefined || typeof h === 'number') && Math.abs(now.height - was.height) > 0.5) {
    node.layoutItem = { ...plain(node.layoutItem), height: Math.round(now.height * 100) / 100 };
  }
  const fixedH = axes.height && typeof node.layoutItem?.height === 'number' ? node.layoutItem.height : undefined;
  if (def && def.sizing.width === 'hug' && was && now && (w === undefined || w === 'hug')) {
    if (Math.abs(now.width - was.width) > 0.5) {
      node.layoutItem = { ...plain(node.layoutItem), width: Math.round(now.width * 100) / 100 }; // the user resized it
    } else {
      try {
        const hug = def.build(resolveProps(def, node.component.props as Record<string, unknown>, node.component.resolved), { width: now.width }).width;
        if (hug && Math.abs(hug - now.width) > 0.5) {
          buildComponentInto(node, { width: Math.ceil(hug), height: fixedH });
          return;
        }
      } catch {
        /* a broken component keeps its box (buildComponentInto reports it) */
      }
    }
  }
  buildComponentInto(node, fixedH !== undefined ? { width: node.component.size?.width ?? def?.defaultSize.width ?? 0, height: fixedH } : undefined);
}

const step: WireframeStep = {
  id: 'components',
  order: 100,
  run(d, ctx) {
    // Traverse a plain snapshot (cheap: the input itself unless an earlier step wrote to the
    // draft); touch the draft only on the path to a rebuilt instance.
    const paths: number[][] = [];
    stale(plain(d).children, ctx, [], paths);
    for (const p of paths) {
      let list = d.children as Draft<SceneNode>[];
      let node: Draft<SceneNode> | undefined;
      for (const i of p) {
        node = list[i];
        list = node.type === 'group' ? node.children : [];
      }
      if (node) rebuildFree(node as Draft<ComponentNode>, ctx);
    }
  },
};

export default step;
